with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('se stort på', 'phrase', '4420fa44-37db-5b37-83e9-793139371250', 1, 'verb', null, 'ігнорувати, не звертати уваги (на щось)', 'Hun ser stort på reglerne og gør, hvad hun vil.', 'Вона ігнорує правила і робить, що хоче.'), ('stå over', 'phrase', '44b4ce38-6967-59bd-944d-b6aa2341866d', 1, 'verb', null, 'пропускати (свою чергу)', 'Jeg står over denne gang.', 'Цього разу я сиджу осторонь.'), ('stå over for', 'phrase', '0d59f120-0b3c-530a-b859-0f9dd65fa6c1', 1, 'verb', null, 'стояти перед (обличчям) (проблемою, вибором)', 'Vi står over for en stor udfordring.', 'Ми стоїмо перед серйозним викликом.'), ('holde sig til', 'phrase', '0e76631b-afc4-5be4-bd55-8a2faef4d4d7', 1, 'verb', null, 'дотримуватися (чогось)', 'Jeg holder mig til de regler, vi har aftalt.', 'Я дотримуюся правил, про які ми домовилися.'), ('gå frem', 'phrase', '85a09b7a-7cd0-58ac-8246-160b43c33c8d', 1, 'verb', null, 'просуватися (вперед)', 'Projektet gik frem hurtigere end forventet.', 'Проєкт просувався швидше, ніж очікувалося.'), ('gå frem', 'phrase', '9a0e8ddb-496d-5271-9f86-0d04348e9093', 2, 'verb', null, 'зростати (про показники)', 'Salget gik frem med ti procent sidste år.', 'Продажі зросли на десять відсотків минулого року.'), ('køre ind', 'phrase', 'ed78d4d2-d8f3-5f2f-997c-841b2f16f797', 1, 'verb', null, 'в''їжджати (всередину)', 'Bilen kører ind i garagen.', 'Автомобіль в''їжджає в гараж.'), ('slå til', 'phrase', '3753aaea-834c-56d1-9d38-74df8343097a', 1, 'verb', null, 'бути достатнім', 'Pengene slog til hele måneden.', 'Грошей вистачило на весь місяць.'), ('slå til', 'phrase', 'b8027f0a-8ca5-5ce2-8c36-7dcc4870a244', 2, 'verb', null, 'погоджуватися (на пропозицію)', 'Hun slog til med det samme.', 'Вона одразу погодилася.'), ('sætte pris på', 'phrase', '22820690-b849-5215-bb93-e546aa62e104', 1, 'verb', null, 'цінувати', 'Jeg sætter pris på din hjælp.', 'Я ціную вашу допомогу.'), ('samle sig', 'phrase', '5410829f-568b-5cbb-8b9c-97f35c6b95ce', 1, 'verb', null, 'зібратися (з думками, силами)', 'Du må samle dig og gøre arbejdet færdigt.', 'Ти маєш зібратися і завершити справу.'), ('stige op', 'phrase', '79813b72-d68a-5d66-8900-81c6288e7ce6', 1, 'verb', null, 'підніматися (вгору)', 'Han steg op ad trappen til anden sal.', 'Він піднявся сходами на другий поверх.'), ('åbne øjnene', 'phrase', '472efb4e-541f-5e80-8d84-4b27ad80eec5', 1, 'verb', null, 'розкривати очі (комусь) на правду', 'Hun åbnede øjnene på mig for problemet.', 'Вона відкрила мені очі на проблему.'), ('komme igennem', 'phrase', '2dce3a6d-a959-5bb1-bfbd-0b085ed81a5f', 1, 'verb', null, 'пройти (через труднощі)', 'Det var en svær tid, men vi kom igennem den sammen.', 'Це був важкий час, але ми пройшли через це разом.'), ('komme igennem', 'phrase', '548f85b0-84fc-5c6f-8d3f-5c03d17c87ca', 2, 'verb', null, 'скласти (іспит)', 'Jeg håber, at jeg kommer igennem eksamen i morgen.', 'Сподіваюся, завтра я здам іспит.'), ('gå fra hinanden', 'phrase', 'e2450623-a12f-5f7e-a814-6e022e8dda4b', 1, 'verb', null, 'розходитися (про пару)', 'De gik fra hinanden efter fem år sammen.', 'Вони розійшлися після п''яти років разом.'), ('skrive hjem', 'phrase', '68b70276-c8b4-56c5-a5fd-2d2c21f2940d', 1, 'verb', null, 'писати додому (повідомляти новини)', 'Hun skrev hjem om sin nye lejlighed.', 'Вона написала додому про свою нову квартиру.'), ('søge efter', 'phrase', '626c5867-14e4-5479-b760-d2d8708f639c', 1, 'verb', null, 'шукати', 'Jeg søger efter mine nøgler overalt.', 'Я шукаю ключі всюди.'), ('løbe med', 'phrase', '3c68c811-7db6-585a-b0d2-35fdae631d31', 1, 'verb', null, 'утікати з (чимсь)', 'Tyven løb med min taske.', 'Злодій утік з моєю сумкою.'), ('løbe rundt', 'phrase', '798120f4-b7d3-5bfb-8f69-556f7218291c', 1, 'verb', null, 'бігати (туди-сюди)', 'Børnene løber rundt i haven hele dagen.', 'Діти цілий день бігають у саду.'), ('kigge efter', 'phrase', '82593d9f-85c9-575c-980d-cd7e72e52362', 1, 'verb', null, 'шукати (очима)', 'Jeg kigger efter mine nøgler overalt.', 'Я шукаю ключі всюди.'), ('stoppe op', 'phrase', '4c62629b-f258-5dcd-9cb3-416de7e31048', 1, 'verb', null, 'зупинятися (на ходу)', 'Bilen stopper op foran lyskrydset.', 'Автомобіль зупиняється перед світлофором.'), ('pege på', 'phrase', 'b80b422e-8712-533b-bb37-78de409755f6', 1, 'verb', null, 'вказувати (на щось)', 'Hun peger på tavlen med en lang pind.', 'Вона вказує на дошку довгою палицею.'), ('gå om bord', 'phrase', '0927ec6f-1ee0-5651-87f5-7bece5ab2808', 1, 'verb', null, 'сідати на корабель (або літак)', 'Passagererne gik om bord i flyet en time før afgang.', 'Пасажири сіли на літак за годину до вильоту.'), ('spise ude', 'phrase', '32a7fcd0-7c3d-5032-8209-8a91a17b36b7', 1, 'verb', null, 'їсти не вдома (в ресторані тощо)', 'Vi spiser ude hver fredag.', 'Щоп''ятниці ми їмо в ресторані.'), ('kæmpe mod', 'phrase', 'd2428959-7179-52ce-9d6b-1b58ae0af966', 1, 'verb', null, 'боротися проти', 'De kæmper mod uretfærdighed hver dag.', 'Вони щодня борються з несправедливістю.'), ('byde på', 'phrase', '02802807-8ada-500d-b466-2dec94507bfe', 1, 'verb', null, 'пропонувати (гостям)', 'Værten bød på kaffe og kage.', 'Господар запропонував каву та торт.'), ('byde på', 'phrase', 'fda70ed0-9648-5b87-8ddf-2ebc7d7c65ac', 2, 'verb', null, 'обіцяти (вказувати)', 'Den mørke himmel byder på regn.', 'Темне небо обіцяє дощ.'), ('glæde sig over', 'phrase', 'e5d7c04d-2931-5da1-8056-6b0f4b5bf7ed', 1, 'verb', null, 'радіти (чомусь)', 'Jeg glæder mig over det gode vejr i dag.', 'Я радію гарній погоді сьогодні.'), ('synge for', 'phrase', '6905e9ed-9e54-5f9a-84ce-46910ab34192', 1, 'verb', null, 'співати для (когось)', 'Hun sang for sin familie til fødselsdagen.', 'Вона співала для своєї родини на день народження.'), ('dække bord', 'phrase', 'a9e79694-91ad-5998-b7b1-22814e425da1', 1, 'verb', null, 'накривати на стіл', 'Hun dækker bord med tallerkener og glas.', 'Вона накриває на стіл тарілками та келихами.'), ('gemme sig under', 'phrase', '3784c77f-f8e3-5696-b6b2-ae1125272fa6', 1, 'verb', null, 'ховатися під', 'Katten gemmer sig under bordet.', 'Кіт ховається під столом.'), ('forberede sig på', 'phrase', '0e510ec2-74a2-5036-9895-47009a3b7d5a', 1, 'verb', null, 'готуватися до (чогось)', 'Vi forbereder os på en lang vinter.', 'Ми готуємося до довгої зими.'), ('gå for vidt', 'phrase', 'e95e8164-5042-58df-a73f-0c818238cfd0', 1, 'verb', null, 'заходити надто далеко', 'Jeg synes, du gik for vidt med den kommentar.', 'Думаю, ти зайшов надто далеко з цим коментарем.'), ('drage i krig', 'phrase', 'a789e11e-1a30-5e03-ac4b-2632f15cde17', 1, 'verb', null, 'йти на війну', 'Kongen drog i krig mod nabolandet.', 'Король пішов війною на сусідню країну.'), ('have sex', 'phrase', 'b59b99ce-3fc0-56d5-96af-a59ee612864b', 1, 'verb', null, 'займатися сексом', 'De har sex hver aften.', 'Вони займаються сексом щовечора.'), ('have en skrue løs', 'phrase', '2ec55c31-8dd7-5639-910e-be8d51617282', 1, 'verb', null, 'мати не всі вдома (бути трохи божевільним)', 'Jeg tror, han har en skrue løs, for han taler hele tiden med sig selv.', 'Думаю, у нього не всі вдома, бо він постійно говорить сам із собою.'), ('sætte ild til', 'phrase', '7a979f67-6303-5389-a067-13b5633ea9f1', 1, 'verb', null, 'підпалювати', 'Nogen har sat ild til skuret bag huset.', 'Хтось підпалив сарай за будинком.'), ('hoppe på', 'phrase', '123b3745-f645-569c-93a6-dec543495f8e', 1, 'verb', null, 'охоче погоджуватися (на щось)', 'Han hoppede på tilbuddet med det samme.', 'Він одразу ж ухопився за пропозицію.'), ('forsyne sig', 'phrase', '38d42a0e-6f50-5c9c-ab19-6a3484e6a969', 1, 'verb', null, 'обслуговувати себе (брати їжу)', 'Gæsterne kan forsyne sig fra buffeten hele aftenen.', 'Гості можуть пригощатися зі шведського столу весь вечір.'), ('skynde sig hjem', 'phrase', '995c6467-bfd8-5b43-9849-3ad28025cf15', 1, 'verb', null, 'поспішати додому', 'Børnene skynder sig hjem efter skole.', 'Діти поспішають додому після школи.'), ('have for vane at', 'phrase', '3ba05aec-f200-50ca-a69d-243e0bb6c343', 1, 'verb', null, 'мати звичку (робити щось)', 'Jeg har for vane at drikke kaffe om morgenen.', 'У мене є звичка пити каву вранці.'), ('pønse på', 'phrase', '4cfc9386-77a9-5d33-b47f-9c9362a0bff9', 1, 'verb', null, 'замишляти (щось погане)', 'De to drenge pønser på en hemmelig plan.', 'Двоє хлопців виношують секретний план.'), ('bugte sig', 'phrase', 'd7444315-60bb-5428-9494-b3724b6a1bd7', 1, 'verb', null, 'звиватися (про дорогу, річку)', 'Stien bugter sig gennem skoven.', 'Стежка звивається крізь ліс.'), ('have hjemve', 'phrase', '05762bca-ac20-54d0-95cc-91be2121c13f', 1, 'verb', null, 'сумувати за домом', 'Hun har hjemve, når hun er på ferie.', 'Вона сумує за домом, коли перебуває у відпустці.'), ('gå med til', 'phrase', '40cc22a2-15af-588d-9936-21de34258d30', 1, 'verb', null, 'погоджуватися (на щось)', 'Hun gik med til at hjælpe os i weekenden.', 'Вона погодилася допомогти нам на вихідних.'), ('løbe fra', 'phrase', 'f4bae7fe-448e-5256-bb35-1a35b9c7f1ea', 1, 'verb', null, 'тікати від', 'Hunden løb fra sin ejer i parken.', 'Собака втік від господаря в парку.'), ('løbe fra', 'phrase', '2d3d3830-9be4-5816-b463-76c6dbec4569', 2, 'verb', null, 'відмовлятися від (обіцянки)', 'Han løb fra aftalen i sidste øjeblik.', 'Він відмовився від угоди в останню хвилину.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'uk'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'uk', text, pos, gender, example, example_translation, 'pipeline-phrases-0006' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
